SourceCode.Declaration:
/// <summary>
/// Extends SysOperationServiceController
/// </summary>
class AVACRLUpdateRiscDebtorController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// new method
/// </summary>
protected void new()
{
    super(classStr(AVACRLUpdateRiscDebtorService), methodStr(AVACRLUpdateRiscDebtorService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// default class description
/// </summary>
/// <returns>ClassDescription</returns>
public ClassDescription defaultCaption()
{
    return "@NDX:NXARiscDebtorUpdate";
}

/// <summary>
/// construct method
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVACRLUpdateRiscDebtorController</returns>
public static AVACRLUpdateRiscDebtorController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACRLUpdateRiscDebtorController controller;
    controller = new AVACRLUpdateRiscDebtorController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    CustTable       custTable;

    if (_args.record() && _args.dataset() == tableNum(CustTable))
    {
        custTable = _args.record();
    }
    AVACRLUpdateRiscDebtorController controller;
    AVACRLUpdateRiscDebtorContract   contract;
    controller = AVACRLUpdateRiscDebtorController::construct();
    contract = controller.getDataContractObject();
    if (CustTable)
    {
        contract.parmRiscDebtor(custTable.AccountNum);
        contract.parmCompany(custTable.DataAreaId);
        controller.parmShowDialog(false);
    }
    else
    {
        controller.initQuery(contract);
        controller.parmShowDialog(true);
    }
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// initQuery method
/// </summary>
/// <param name = "_dataContract">AVACRLUpdateRiscDebtorContract</param>
/// <returns>Query</returns>
internal Query initQuery(AVACRLUpdateRiscDebtorContract _dataContract)
{
    Query                query;
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange      queryBuildRange;

    query = new Query(queryStr(AVACRLUpdateRiscDebtorQuery));

    queryBuildDataSource = sysQuery::findOrCreateDataSource(query,tableNum(CredManCreditLimitCustGroup));

    queryBuildRange = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(CredManCreditLimitCustGroup, AVACompanyId));
    queryBuildRange.value(SysQuery::value(curExt()));
    queryBuildRange.status(RangeStatus::Locked);

    _dataContract.parmQuery(SysOperationHelper::base64Encode(query.pack()));

    return query;
}
